type State = "open" | "paid";
export function label(state: State): string {
  switch (state) {
    case "open": return "Open";
    case "paid": return "Paid";
    default: { const unreachable: never = state; return unreachable; }
  }
}
export const FETCH_TIMEOUT_MS = 2000;

